# Find connected components for each color
import collections
visited = [[False]*29 for _ in range(20)]
boxes = collections.defaultdict(list)

def find_region(r, c, color):
    region = [(r, c)]
    visited[r][c] = True
    stack = [(r, c)]
    while stack:
        rr, cc = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < 20 and 0 <= nc < 29:
                if not visited[nr][nc] and grid[nr][nc] == color:
                    visited[nr][nc] = True
                    region.append((nr, nc))
                    stack.append((nr, nc))
    return region

for r in range(20):
    for c in range(29):
        if grid[r][c] != 4 and not visited[r][c]:
            region = find_region(r, c, grid[r][c])
            rows = sorted(set(p[0] for p in region))
            cols = sorted(set(p[1] for p in region))
            boxes[grid[r][c]].append((rows[0], rows[-1], cols[0], cols[-1], len(region)))

